import math

def k(x,y,sigma2=1.0,lam=1.0):
    r=math.sqrt(sum((a-b)**2 for a,b in zip(x,y)))
    z=math.sqrt(5)*r/lam
    return sigma2*(1+z+z*z/3)*math.exp(-z)

def trace_numeric(x,y,h=1e-4):
    out=0.0
    for j in range(len(x)):
        xp=x.copy(); xm=x.copy(); yp=y.copy(); ym=y.copy()
        xp[j]+=h; xm[j]-=h; yp[j]+=h; ym[j]-=h
        out+=(k(xp,yp)-k(xp,ym)-k(xm,yp)+k(xm,ym))/(4*h*h)
    return out

def trace_printed(x,y):
    r2=sum((a-b)**2 for a,b in zip(x,y)); r=math.sqrt(r2)
    return (5/3)*(1+math.sqrt(5)*r-5*r2)*math.exp(-math.sqrt(5)*r)

def trace_correct(x,y):
    d=len(x);r2=sum((a-b)**2 for a,b in zip(x,y));r=math.sqrt(r2)
